 .claude-workboard{--fg2:#a4b1ca;background:#202633;color:#eaf0fc;border:1px solid #303a4f;border-radius:22px;padding:28px;font-family:'Segoe UI','Malgun Gothic',sans-serif}.board-title{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.board-title p{font-size:9px;letter-spacing:2px;color:#8da0c1;margin:0 0 16px}.board-title h2{font-size:23px;letter-spacing:-.6px;margin:0 0 12px}.board-title span{font-size:12px;color:#a5b4ce}.board-title .board-role{font-size:10px;background:#33413b;color:#a7d8bc;padding:8px 12px;border-radius:20px;white-space:nowrap}.state-chips{display:flex;gap:8px;margin:28px 0 20px;flex-wrap:wrap}.state-chips button{display:flex;align-items:center;gap:8px;background:#2b3342;border:1px solid #3b4558;border-radius:30px;padding:10px 13px;color:#bbc8de;font:inherit;font-size:12px}.state-chips button.chosen{background:#43516b;color:white;border-color:#7186aa}.state-chips b{font-variant-numeric:tabular-nums;background:#ffffff0c;padding:2px 6px;border-radius:6px}.board-controls{display:flex;gap:8px;flex-wrap:wrap}.board-controls input,.board-controls select,.board-controls button{font:inherit;font-size:11px;color:#d3def0;background:#2b3342;border:1px solid #414c61;border-radius:8px;padding:11px;width:auto}.board-controls input{flex:1;min-width:190px}.board-controls input::placeholder{color:#8c9bb4}.board-controls button:hover{background:#39455b}button{cursor:pointer}.board-summary{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:#9aacc8;margin:24px 0 16px}.board-summary small{font-size:10px}.group-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;align-items:start}.group-grid.compact{grid-template-columns:repeat(3,minmax(0,1fr))}.board-empty{grid-column:1/-1;text-align:center;padding:55px 20px;color:#a6b6d1}.board-empty strong{color:#d9e3f5;font-size:18px}.board-empty p{font-size:12px;line-height:1.8}.board-credit{font-size:10px;line-height:1.8;color:#8595b0;margin:26px 0 0}.board-credit a{color:#a9bad5;margin-left:8px}@media(max-width:1100px){.group-grid,.group-grid.compact{grid-template-columns:1fr}}@media(max-width:650px){.claude-workboard{padding:20px 14px;border-radius:16px}.board-title h2{font-size:19px}.board-title .board-role{display:none}.board-summary{flex-direction:column}.state-chips{gap:5px}.state-chips button{padding:8px;font-size:10px}}
</style>
